#include <stdio.h>
int bsearch_int(const int *a, size_t n, int key) { size_t lo=0,hi=n; while(lo<hi) { size_t mid=lo+(hi-lo)/2; if(a[mid]<key) lo=mid+1; else hi=mid; } return lo<n && a[lo]==key ? (int)lo : -1; }
int main(void) { int a[]={2,5,9,14}; printf("%d\n",bsearch_int(a,4,9)); return 0; }
